/**
 * Transcribe a short recording of the caller speaking, for dictating a message. The recording is WebM, MP4 or WAV audio under 10 MiB, and is not kept. One recording at a time for each person.
 * @summary Turn a recording into text
 */
export const createTranscription = async (
  organizationId: string,
  transcriptionUpload: TranscriptionUpload,
  headers: CreateTranscriptionHeaders,
  options?: Parameters<typeof apiRequest>[1],
): Promise<Transcription> => {
  const formData = new FormData();
  formData.append(`file`, transcriptionUpload.file);

  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiRequest<Transcription>(getCreateTranscriptionUrl(organizationId), {
    ...options,
    method: "POST",
    headers: { ...headers, ...getHeaders(options?.headers) },
    body: formData,
  });
};

